// Generates build/installer-languages.nsh from src/locales/languages.js.
//
// The NSIS setup wizard shows a 73-language picker before anything is installed
// and preselects the Windows display language, falling back to English. The
// generated file keeps that list identical to the in-app registry, so a locale
// can never exist in the app but be missing from the installer (or the reverse).
//
// Run: node tools/gen-installer-languages.js
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const languages = require(path.join(ROOT, 'src', 'locales', 'languages.js'));

const escape = (value) => String(value).replace(/"/g, '""').replace(/\$/g, '$$$$');

// Language codes whose Windows locale name starts with the same two letters but
// must be compared on three characters first (fil before fi, etc.).
const threeLetter = languages.map((lang) => lang.code).filter((code) => code.length === 3);

const items = languages
    .map((lang) => {
        const label = lang.name && lang.name !== lang.english
            ? `${lang.name} (${lang.english})`
            : lang.english;
        return `    !insertmacro TACTILE_ADD_LANG "${escape(lang.code)}" "${escape(label)}"`;
    })
    .join('\n');

const detect = [];
// Three-letter codes must be compared before any two-letter code that shares
// their prefix (fil before fi).
detect.push('    StrCpy $2 $1 3');
for (const code of threeLetter) {
    detect.push(`    StrCmp $2 "${code}" tact_lang_${code.replace(/-/g, '_')}`);
}
detect.push('    StrCpy $2 $1 2');
for (const lang of languages) {
    if (lang.code.length !== 2) continue;
    detect.push(`    StrCmp $2 "${lang.code}" tact_lang_${lang.code}`);
}
detect.push('    Goto tact_lang_done');

const labels = [];
for (const lang of languages) {
    labels.push(`tact_lang_${lang.code.replace(/-/g, '_')}:`);
    labels.push(`    StrCpy $0 "${lang.code}"`);
    labels.push('    Goto tact_lang_done');
}

const selections = [];
languages.forEach((lang, index) => {
    selections.push(`    StrCmp $TactileSelectedLanguage "${lang.code}" 0 +3`);
    selections.push(`    SendMessage $TactileLangCombo \${CB_SETCURSEL} ${index} 0`);
    selections.push('    Goto tact_select_done');
});

// Reverse mapping used when the wizard closes: list index -> language code.
const codes = languages.map((lang, index) => `    StrCmp $1 ${index} 0 +2\n    StrCpy $9 "${lang.code}"`);

const output = `; AUTO-GENERATED by tools/gen-installer-languages.js - do not edit by hand.
; ${languages.length} languages, one entry per locale in src/locales.

!macro TACTILE_LANGUAGE_ITEMS
${items}
!macroend

; Maps the Windows locale name (HKCU\\Control Panel\\International\\LocaleName,
; e.g. "tr-TR", "zh-Hans-CN") to a Tactile language code, English by default.
Function TactileDetectInstallerLanguage
    StrCpy $0 "en"
    ReadRegStr $1 HKCU "Control Panel\\International" "LocaleName"
    StrCmp $1 "" tact_lang_done
    ; Chinese locale names carry the script, so they are matched in full first.
    StrCmp $1 "zh-Hant" tact_lang_zh_TW
    StrCmp $1 "zh-HK" tact_lang_zh_TW
    StrCmp $1 "zh-MO" tact_lang_zh_TW
    StrCmp $1 "zh-CN" tact_lang_zh_CN
    StrCmp $1 "zh-SG" tact_lang_zh_CN
    StrCmp $1 "zh-Hans" tact_lang_zh_CN
    StrCpy $2 $1 2
    StrCmp $2 "zh" tact_lang_zh_CN
${detect.join('\n')}

${labels.join('\n')}

    tact_lang_done:
FunctionEnd

; Selects the detected language inside the already-populated combobox.
Function TactileSelectInstallerLanguage
${selections.join('\n')}
    tact_select_done:
FunctionEnd

; Pops a combobox index and pushes the matching language code (English when the
; index is unknown). Used when the language page is confirmed.
Function TactileLanguageCodeFromIndex
    Pop $1
    StrCpy $9 "en"
${codes.join('\n')}
    Push $9
FunctionEnd
`;

fs.writeFileSync(path.join(ROOT, 'build', 'installer-languages.nsh'), output, 'utf8');
console.log(`installer languages: ${languages.length}`);
